BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY; SET LOCAL statement_timeout='20s'; SELECT jsonb_build_object('activity_since_foundation',(SELECT jsonb_agg(jsonb_build_object('action',a.action,'created_at',a.created_at,'related_type',a.related_type,'actor_alias',left(encode(sha256(convert_to(a.actor_user_id::text,'UTF8')),'hex'),16))) FROM public.activity_logs a WHERE a.created_at>'2026-10-11T22:14:28.755Z'),'auth_users_updated_since_foundation',(SELECT jsonb_agg(jsonb_build_object('owner_alias',left(encode(sha256(convert_to(u.id::text,'UTF8')),'hex'),16),'created_at',u.created_at,'updated_at',u.updated_at,'last_sign_in_at',u.last_sign_in_at,'role',u.role,'provider',u.raw_app_meta_data->>'provider')) FROM auth.users u WHERE u.updated_at>'2026-10-11T22:14:28.755Z'),'auth_identities_updated_since_foundation',(SELECT jsonb_agg(jsonb_build_object('owner_alias',left(encode(sha256(convert_to(i.user_id::text,'UTF8')),'hex'),16),'created_at',i.created_at,'updated_at',i.updated_at,'provider',i.provider)) FROM auth.identities i WHERE i.updated_at>'2026-10-11T22:14:28.755Z'),'admin_sessions_created_since_foundation',(SELECT jsonb_agg(jsonb_build_object('created_at',s.created_at,'expires_at',s.expires_at,'revoked',s.revoked_at IS NOT NULL,'last_used_at',s.last_used_at,'admin_alias',left(encode(sha256(convert_to(s.admin_id::text,'UTF8')),'hex'),16))) FROM public.admin_sessions s WHERE s.created_at>'2026-10-11T22:14:28.755Z')) evidence; ROLLBACK;
